# DOCX and PPTX Text Extraction

## Installation
```bash
pip install python-docx python-pptx
```

## DOCX Text Extraction

```python
from docx import Document

def extract_docx_text(filepath):
    doc = Document(filepath)
    text = []
    for para in doc.paragraphs:
        text.append(para.text)
    return "\n".join(text)
```

## PPTX Text Extraction

```python
from pptx import Presentation

def extract_pptx_text(filepath):
    prs = Presentation(filepath)
    text = []
    for slide in prs.slides:
        for shape in slide.shapes:
            if hasattr(shape, "text"):
                text.append(shape.text)
    return "\n".join(text)
```

## Fallback: ZIP-based extraction (no libraries needed)
DOCX and PPTX files are ZIP archives containing XML. You can extract text without libraries:

```python
import zipfile
import xml.etree.ElementTree as ET

def extract_docx_text_fallback(filepath):
    """Extract text from DOCX using raw XML parsing."""
    with zipfile.ZipFile(filepath) as z:
        with z.open('word/document.xml') as f:
            tree = ET.parse(f)
            root = tree.getroot()
            ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
            texts = [node.text for node in root.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}t') if node.text]
            return ' '.join(texts)

def extract_pptx_text_fallback(filepath):
    """Extract text from PPTX using raw XML parsing."""
    with zipfile.ZipFile(filepath) as z:
        texts = []
        for name in z.namelist():
            if name.startswith('ppt/slides/slide') and name.endswith('.xml'):
                with z.open(name) as f:
                    tree = ET.parse(f)
                    root = tree.getroot()
                    for node in root.iter('{http://schemas.openxmlformats.org/drawingml/2006/main}t'):
                        if node.text:
                            texts.append(node.text)
        return ' '.join(texts)
